CREATE TABLE topics (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE sessions (
  id INTEGER PRIMARY KEY,
  topic_id INTEGER NOT NULL REFERENCES topics(id),
  minutes INTEGER CHECK (minutes >= 0),
  status TEXT NOT NULL CHECK (status IN ('done', 'planned'))
);

INSERT INTO topics (id, name) VALUES
  (1, 'SQL'), (2, 'Web'), (3, 'Review'), (4, 'Notes');

INSERT INTO sessions (id, topic_id, minutes, status) VALUES
  (1, 1, 20, 'done'),
  (2, 2, 30, 'done'),
  (3, 1, 35, 'done'),
  (4, 2, 15, 'planned'),
  (5, 3, 20, 'done'),
  (6, 3, NULL, 'planned'),
  (7, 1, 20, 'done');

SELECT minutes, id
FROM sessions
ORDER BY id;

import sqlite3
from contextlib import closing

with closing(sqlite3.connect(":memory:")) as db:
    db.executescript("""
        CREATE TABLE sessions (id INTEGER PRIMARY KEY, status TEXT);
        INSERT INTO sessions VALUES (1, 'done'), (2, 'planned');
    """)
    query = "SELECT id FROM sessions WHERE status = ?"
    for (session_id,) in db.execute(query, ("done",)):
        print(session_id)

